import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';

export default function Navbar() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  return (
    <header className="bg-white text-slate-900 border-b border-gray-100 sticky top-0 z-50">
      <div className="max-w-6xl mx-auto px-6 py-4 flex justify-between items-center">
        {/* โลโก้ร้านสี่เหลี่ยมมุมมนสีน้ำเงิน */}
        <Link to="/" className="flex items-center space-x-2.5 text-lg font-extrabold tracking-tight">
          <span className="w-7 h-7 rounded-lg bg-[#1d64f2] inline-block"></span>
          <span>[ชื่อร้าน]</span>
        </Link>

        {/* เมนูหลัก */}
        <nav className="hidden md:flex items-center space-x-7 text-sm text-gray-600 font-medium">
          <Link to="/cars" className="hover:text-[#1d64f2] transition">รถของเรา</Link>
          <a href="/#steps" className="hover:text-[#1d64f2] transition">ขั้นตอนการเช่า</a>
          <a href="/#terms" className="hover:text-[#1d64f2] transition">เงื่อนไข</a>
          {user && (
            <>
              <Link to="/my-bookings" className="hover:text-[#1d64f2] transition">การจองของฉัน</Link>
              <Link to="/profile" className="hover:text-[#1d64f2] transition">โปรไฟล์</Link>
            </>
          )}
          {user?.role === 'admin' && (
            <Link to="/admin" className="bg-blue-50 text-[#1d64f2] border border-blue-200 px-3 py-1 rounded-lg font-bold text-xs">
              Admin Panel
            </Link>
          )}
        </nav>

        {/* ปุ่ม Login / Register / Logout */}
        <div className="flex items-center space-x-4 text-sm font-medium">
          {user ? (
            <>
              <span className="text-gray-600 hidden sm:inline">สวัสดี, {user.full_name}</span>
              <button
                onClick={handleLogout}
                className="border border-gray-300 text-gray-700 px-4 py-1.5 rounded-lg hover:bg-gray-50 transition"
              >
                ออกจากระบบ
              </button>
            </>
          ) : (
            <>
              <Link to="/login" className="text-gray-600 hover:text-[#1d64f2] transition">เข้าสู่ระบบ</Link>
              <Link
                to="/register"
                className="bg-[#1d64f2] text-white font-semibold px-4 py-2 rounded-lg hover:bg-blue-700 transition shadow-sm"
              >
                สมัครสมาชิก
              </Link>
            </>
          )}
        </div>
      </div>
    </header>
  );
}
